	model: Model<"anthropic-messages">,
	context: TranscriptContext,
	options?: SimpleStreamOptions,
): AssistantMessageEventStream => {
	context = asTranscriptContext(context);
	const apiKey = resolveVendoredAnthropicApiKey(options);
	if (!apiKey) {
		throw new Error(`No API key for provider: ${model.provider}`);
	}
	const thinkingDisplay = (options as (SimpleStreamOptions & {
		thinkingDisplay?: AnthropicThinkingDisplay;
	}) | undefined)?.thinkingDisplay;
	const base = {
		...buildBaseOptions(model, context, options, apiKey),
		...(thinkingDisplay === undefined ? {} : { thinkingDisplay }),
	} as AnthropicOptions;
	if (!options?.reasoning) {
		return streamAnthropic(model, context, { ...base, thinkingEnabled: false });
	}

	// For modern Claude 4.x adaptive models: use adaptive thinking with effort level
	// For older models: use budget-based thinking
	if (supportsAdaptiveThinking(model)) {
		const hasExplicitNullEffort =
			model.thinkingLevelMap !== undefined &&
			Object.prototype.hasOwnProperty.call(model.thinkingLevelMap, options.reasoning) &&
			model.thinkingLevelMap[options.reasoning] === null;
		return streamAnthropic(model, context, {
			...base,
			thinkingEnabled: true,
			effort: hasExplicitNullEffort
				? undefined
				: mapThinkingLevelToEffort(options.reasoning, model),
			...(hasExplicitNullEffort ? { thinkingDisplay: "omitted" as const } : {}),
		} satisfies AnthropicOptions);
	}

	const adjusted = adjustMaxTokensForThinking(
		base.maxTokens || 0,
		model.maxTokens,
		options.reasoning,
		options.thinkingBudgets,
	);

